        private promiseZmenaKurzuBeznehoDokladu(dotaz: boolean, datOdp: Date, datOdu: Date, ixp: string, kurz: JsonDecimal): JQueryPromise<void> {
            var that = this;

            let def = $.Deferred();

            that.isl.PokDoklad.zmenitKurzBeznehoDokladu(rq => {
                return {
                    dotazKontrolaRozpoctu: dotaz,
                    datOdp: datOdp,
                    datOdu: datOdu,                   
                    ixp: ixp,
                    kurz: kurz
                }
            })
                .get()
                .done(function () {

                    return def.resolve();

                })
                .fail(function (xhr, type, vobj) {
                    if (type === "exception") {
                        if (vobj.baseType === "Gordic.General.GHplValidationException") {
                            vobj.handled = true;
                            return def.reject(vobj.baseMessage);

                        }
                        else if (vobj.data.member == "dotazKontrolaRozpoctu") {
                            vobj.handled = true;
                            //když je to hromadně tak tam dotaz není, bude se hodit pak na přecenění na detailu

                            //return that.dialogs.confirm(vobj.baseMessage).createDialogPromise([GDlg.mbbYes.id, GDlg.mbbNo.id])
                            //    .then(function (retVal) {
                            //        if (retVal === GDlg.mbbYes.id) {
                                        return that.promiseZmenaKurzuBeznehoDokladu(false, datOdp, datOdu, ixp, kurz).done(function () { def.resolve() }).fail(function () { def.reject() });
                                //    }
                                //    else {
                                //        def.reject();
                                //    }
                                   
                                //});

                        }
                        else {
                            return def.reject();
                        }
                    }
                })

            return def.promise();

        }

